/* global window, document, localStorage */
/* Shared POS receipt template helpers + HTML builder for the desktop app.
   Mirrors the accounting-web-app receipt design (POSReceipt.tsx). */

'use strict';

(function (global) {
  var RECEIPT_KEY = 'pos_receipt_template_v1';

  function DEFAULT_RECEIPT_TEMPLATE() {
    return {
      storeName: '',
      storeAddress: '',
      // NOTE: keys mirror the accounting-web-app PosReceiptTemplate exactly
      // (phone/email/website) because both apps share the same backend
      // receipt-settings metadata.
      phone: '',
      email: '',
      website: '',
      storeLogo: '',
      taxId: '',
      showLogo: true,
      showAddress: true,
      showPhone: true,
      showEmail: true,
      showWebsite: true,
      showTaxId: true,
      showBarcode: true,
      showSku: true,
      showLoyalty: true,
      showCashier: true,
      showTerminal: true,
      receiptHeader: 'TAX INVOICE / SALES RECEIPT',
      receiptFooter: 'Thank you for shopping with us! Please visit again.',
      receiptReturnPolicy:
        'Returns accepted within 7 days with this original receipt. Opened, used or clearance items are non-refundable. Please inspect goods before leaving the store.',
      receiptNotes:
        'This is a computer-generated receipt and is valid without a signature. Please retain this copy for warranty, returns and accounting records.',
      copyLabel: 'ORIGINAL CUSTOMER COPY',
      servedByPrefix: 'You were served by',
      poweredBy: 'Powered by FastNxt POS',
      thermalPaperWidthMm: 80,
      // Local POS setting: cashier must type cash the customer handed over.
      askCashReceived: false,
    };
  }

  function loadReceiptTemplate() {
    try {
      var raw = localStorage.getItem(RECEIPT_KEY);
      var stored = raw ? JSON.parse(raw) : {};
      return Object.assign(DEFAULT_RECEIPT_TEMPLATE(), stored);
    } catch (e) {
      return DEFAULT_RECEIPT_TEMPLATE();
    }
  }

  function saveReceiptTemplate(next) {
    var merged = Object.assign(loadReceiptTemplate(), next || {});
    try {
      localStorage.setItem(RECEIPT_KEY, JSON.stringify(merged));
    } catch (e) {
      /* ignore quota */
    }
    try {
      global.dispatchEvent(new CustomEvent('pos:receipt-template-changed', { detail: merged }));
    } catch (e) {
      /* ignore */
    }
    return merged;
  }

  // Main app brand logo (FastNxt). Embedded as base64 data URI so it renders
  // everywhere: page DOM, print windows (about:blank), and the packaged app.
  var APP_LOGO_FILE = '../../assets/icon.png'; // relative fallback
  var APP_LOGO_DATA = 'data:image/png;base64,';
  var APP_LOGO = APP_LOGO_DATA || APP_LOGO_FILE;
  function resolveReceiptCompany(profile, template) {
    var bd = (profile && profile.businessDetails) || {};
    var comp = (profile && profile.company) || {};
    var tpl = template || loadReceiptTemplate();
    return {
      name:
        tpl.storeName ||
        (profile && profile.companyName) ||
        bd.businessName ||
        bd.companyName ||
        comp.name ||
        (profile && profile.organizationName) ||
        (profile && profile.name) ||
        'POS',
      logo: tpl.storeLogo || (profile && profile.logo) || bd.logo || comp.logo || '',
      address: tpl.storeAddress || bd.address || comp.address || '',
      phone: tpl.phone || tpl.storePhone || bd.phone || comp.phone || (profile && profile.phone) || '',
      email: tpl.email || tpl.storeEmail || bd.email || comp.email || (profile && profile.email) || '',
      website: tpl.website || tpl.storeWebsite || bd.website || comp.website || (profile && profile.website) || '',
      taxId: tpl.taxId || bd.taxId || comp.taxId || '',
    };
  }

  function money(n) {
    var v = Number(n);
    if (!isFinite(v)) v = 0;
    return 'PKR ' + v.toFixed(2);
  }

  function formatReceiptQty(item) {
    var qty = asNumber(item && item.quantity, 0);
    var unit = String((item && (item.unitName || item.salesUnitName || item.stockUnitName)) || 'Pcs').trim() || 'Pcs';
    var text = Number.isInteger(qty) ? String(qty) : String(Math.round(qty * 1000) / 1000);
    return text + ' ' + unit;
  }

  function asNumber(v, fallback) {
    if (v == null || v === '') return fallback || 0;
    if (typeof v === 'object') {
      v = v.rate != null ? v.rate
        : v.value != null ? v.value
        : v.percentage != null ? v.percentage
        : v.taxRate != null ? v.taxRate
        : fallback || 0;
    }
    var n = Number(v);
    return isFinite(n) ? n : (fallback || 0);
  }

  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function itemCount(sale) {
    var items = (sale && sale.items) || [];
    return items.reduce(function (sum, i) { return sum + asNumber(i.quantity, 0); }, 0);
  }

  function lineTotal(item) {
    var explicit = asNumber(item.lineTotal, NaN);
    if (isFinite(explicit) && explicit > 0) return explicit;
    return asNumber(item.quantity, 0) * asNumber(item.unitPrice, 0);
  }

  // Screen + thermal: normal body (400), bold only for labels/TOTAL. Heavy stroke/shadow blobs on thermal.
  function row(label, value, strong, large) {
    return '<table style="width:100%;border-collapse:collapse;font-size:' + (large ? 14 : 12) + 'px;font-weight:' + (strong ? 700 : 400) + ';"><tbody><tr>' +
      '<td style="text-align:left;padding:1px 8px 1px 0;vertical-align:top;">' + esc(label) + '</td>' +
      '<td style="text-align:right;padding:1px 0;vertical-align:top;white-space:nowrap;">' + esc(value == null ? '' : value) + '</td>' +
      '</tr></tbody></table>';
  }

  // ─── Receipt HTML builder (web-style thermal) ───────────────────────────────
  function buildReceiptHtml(sale, company, template) {
    var tpl = template || loadReceiptTemplate();
    var comp = company || { name: 'FastNxt POS', logo: '', address: '', phone: '', email: '', website: '', taxId: '' };
    var s = sale || {};
    var items = s.items || [];
    var payments = s.payments || [];
    var sold = new Date(s.createdAt || Date.now());
    var invoice = s.invoiceNumber || s.orderNo || 'RECEIPT';
    var paperWidth = Number(tpl.thermalPaperWidthMm) === 58 ? 280 : 360;
    var dash = '<div style="border-top:1px dashed #000;margin:10px 0;"></div>';

    var header = '';
    if (tpl.showLogo && comp.logo) {
      header += '<div style="text-align:center;margin-bottom:6px;"><img src="' + esc(comp.logo) + '" alt="' + esc(comp.name) + '" style="height:56px;max-width:160px;object-fit:contain;"/></div>';
    }
    header += '<div style="text-align:center;">';
    header += '<div style="font-size:15px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;">' + esc(comp.name) + '</div>';
    if (tpl.showAddress && comp.address) header += '<div style="font-size:12px;font-weight:400;margin-top:4px;">' + esc(comp.address) + '</div>';
    if (tpl.showPhone && comp.phone) header += '<div style="font-size:12px;font-weight:400;">Tel: ' + esc(comp.phone) + '</div>';
    if (tpl.showEmail && comp.email) header += '<div style="font-size:12px;font-weight:400;">' + esc(comp.email) + '</div>';
    if (tpl.showWebsite && comp.website) header += '<div style="font-size:12px;font-weight:400;">' + esc(String(comp.website).replace(/^https?:\/\//, '')) + '</div>';
    if (tpl.showTaxId && comp.taxId) header += '<div style="font-size:12px;font-weight:400;margin-top:4px;">NTN / Tax ID: ' + esc(comp.taxId) + '</div>';
    header += '</div>';

    // Return receipts: prominent banner + original invoice reference
    if (s.receiptTitle) {
      header += '<div style="text-align:center;margin-top:6px;font-size:13px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;">' + esc(s.receiptTitle) + '</div>';
    }

    var meta = row('Receipt #', invoice) + row('Date', sold.toLocaleDateString()) + row('Time', sold.toLocaleTimeString());
    if (s.originalInvoice) meta += row('Original inv', s.originalInvoice);
    if (s.customerName || (s.customer && s.customer.name)) meta += row('Customer', s.customerName || s.customer.name);
    if (tpl.showTerminal) {
      var term = s.terminalName || (s.terminal && s.terminal.name) || (s.shift && s.shift.terminal && s.shift.terminal.name) || '';
      if (term) meta += row('Terminal', term);
    }
    if (tpl.showCashier) {
      var cashier = s.cashierName || (s.cashier && [s.cashier.firstName, s.cashier.lastName].filter(Boolean).join(' ')) || (s.shift && s.shift.cashier && [s.shift.cashier.firstName, s.shift.cashier.lastName].filter(Boolean).join(' ')) || '';
      if (cashier) meta += row('Cashier', cashier);
    }
    if (s.status) meta += row('Status', String(s.status));

    var itemsTable = '';
    items.forEach(function (it) {
      var qtyLabel = formatReceiptQty(it);
      var unit = asNumber(it.unitPrice, 0);
      var amt = lineTotal(it);
      var taxPct = asNumber(it.taxRate, 0);
      var discPct = asNumber(it.discount, 0);
      var skuLine = '';
      if (tpl.showSku) {
        skuLine += '<div style="font-size:11px;font-weight:400;">' + (it.sku ? 'SKU ' + esc(it.sku) : 'SKU \u2014');
        if (it.barcodeNumber) skuLine += '  \u00b7  ' + esc(it.barcodeNumber);
        skuLine += '</div>';
      }
      var sub = qtyLabel + ' \u00d7 ' + money(unit);
      if (discPct) sub += '  Disc ' + discPct + '%';
      if (taxPct) sub += '  Tax ' + taxPct + '%';
      itemsTable += '<div style="margin:8px 0;"><div style="font-weight:700;text-transform:uppercase;">' + esc(it.productName || it.name || 'Item') + '</div>' +
        skuLine +
        '<table style="width:100%;border-collapse:collapse;font-size:12px;font-weight:400;"><tbody><tr>' +
        '<td style="padding-top:2px;text-align:left;">' + esc(sub) + '</td>' +
        '<td style="padding-top:2px;text-align:center;width:56px;">' + esc(qtyLabel) + '</td>' +
        '<td style="padding-top:2px;text-align:right;width:88px;">' + money(amt) + '</td>' +
        '</tr></tbody></table></div>';
    });
    var totals =
      row('No. of items', String(itemCount(s))) +
      row('Subtotal', money(asNumber(s.subtotal, 0))) +
      (asNumber(s.discountTotal, 0) > 0 ? row('Discount', '-' + money(asNumber(s.discountTotal, 0))) : '') +
      (asNumber(s.taxTotal, 0) > 0 ? row('Tax', money(asNumber(s.taxTotal, 0))) : '') +
      dash +
      row('TOTAL', money(asNumber(s.grandTotal, 0)), true, true);

    var paidAmt = asNumber(s.paidAmount, 0);
    if (!paidAmt && payments.length) {
      paidAmt = payments.reduce(function (sum, p) { return sum + asNumber(p.amount, 0); }, 0);
    }
    var billTotal = asNumber(s.grandTotal, 0);
    var changeAmt = asNumber(s.changeAmount, 0);
    if (!changeAmt && paidAmt > billTotal) changeAmt = paidAmt - billTotal;

    var pay = '<div style="font-weight:700;margin-bottom:4px;">PAYMENT</div>';
    if (payments.length) {
      pay += payments.map(function (p) {
        return row(p.reference ? String(p.paymentMethod) + ' \u00b7 ' + p.reference : String(p.paymentMethod || 'Payment'), money(p.amount));
      }).join('');
    }
    if (tpl.askCashReceived) {
      pay += row('Bill total', money(billTotal));
      pay += row('Cash received', money(paidAmt));
      pay += row('Change / remaining', money(Math.max(0, changeAmt)), true, true);
    } else {
      pay += row(payments.length ? 'Amount paid' : 'Paid', money(paidAmt));
      if (changeAmt > 0) pay += row('Change due', money(changeAmt));
    }
    if (tpl.showLoyalty && Number(s.loyaltyPoints) > 0) pay += row('Loyalty points earned', String(s.loyaltyPoints));
    if (s.notes) pay += dash + '<div style="font-size:11px;"><span style="font-weight:700;">Notes: </span>' + esc(s.notes) + '</div>';

    var lower = '';
    if (tpl.showBarcode !== false) {
      var bcVal = receiptBarcodeValue(s);
      var bcSvg = code128BarcodeSvg(bcVal, paperWidth);
      lower += dash;
      // Placeholder filled by applyLabelScanCodes() with Labels page barcode/QR design
      lower += '<div class="receipt-scan-codes" data-receipt-code="' + esc(bcVal) + '" data-paper-width="' + paperWidth + '" style="display:flex;flex-direction:column;align-items:center;justify-content:center;padding:8px 0 4px;overflow:hidden;">' +
        bcSvg +
        '<div style="text-align:center;font-size:10px;font-weight:400;margin-top:4px;">Scan code = receipt #</div>' +
        '</div>';
    }
    if (tpl.receiptReturnPolicy) lower += '<div style="text-align:center;font-size:11px;font-weight:400;white-space:pre-wrap;">' + esc(tpl.receiptReturnPolicy) + '</div>';
    if (tpl.receiptNotes) lower += '<div style="text-align:center;font-size:11px;font-weight:400;margin-top:8px;white-space:pre-wrap;">' + esc(tpl.receiptNotes) + '</div>';
    if (tpl.receiptFooter) lower += '<div style="text-align:center;font-weight:400;margin-top:12px;">' + esc(tpl.receiptFooter) + '</div>';
    if (tpl.servedByPrefix) lower += '<div style="text-align:center;font-size:11px;font-weight:400;margin-top:8px;">' + esc(tpl.servedByPrefix) + ' ' + esc(s.cashierName || 'our team') + '</div>';
    lower += '<div style="text-align:center;font-size:11px;font-weight:400;margin-top:4px;">Generated ' + new Date().toLocaleString() + '</div>';
    if (tpl.poweredBy) lower += '<div style="text-align:center;font-size:11px;font-weight:400;margin-top:2px;">' + esc(tpl.poweredBy) + '</div>';

    return '<div class="pos-receipt-paper" style="width:' + paperWidth + 'px;max-width:100%;margin:0 auto;background:#fff;color:#000;font-family:Courier New,Courier,monospace;">' +
      '<div style="padding:14px 12px;font-size:13px;line-height:1.35;font-weight:400;color:#000;">' +
      header + dash +
      '<div style="text-align:center;font-weight:700;letter-spacing:1.4px;font-size:12px;">' + esc(tpl.receiptHeader) + '</div>' +
      (tpl.copyLabel ? '<div style="text-align:center;font-size:11px;font-weight:400;margin-top:2px;">' + esc(tpl.copyLabel) + '</div>' : '') +
      dash + meta + dash +
      '<div style="font-weight:700;">BILL TO</div><div style="font-weight:400;">' + esc(s.customerName || 'Walk-in Customer') + '</div>' +
      (s.customerPhone ? '<div style="font-weight:400;">Phone: ' + esc(s.customerPhone) + '</div>' : '') +
      (s.customerEmail ? '<div style="font-weight:400;">Email: ' + esc(s.customerEmail) + '</div>' : '') +
      dash +
      '<table style="width:100%;border-collapse:collapse;font-size:12px;font-weight:700;border-bottom:1px dashed #000;"><tbody><tr>' +
      '<td style="padding:0 0 4px;text-align:left;">ITEM</td>' +
      '<td style="padding:0 0 4px;text-align:center;width:36px;">QTY</td>' +
      '<td style="padding:0 0 4px;text-align:right;width:88px;">AMOUNT</td>' +
      '</tr></tbody></table>' + itemsTable +
      dash + totals + dash + pay +
      lower +
      '</div></div>';
  }

  // ─── Barcode (Code128 → inline SVG, scannable on phone / USB scanners) ─────
  var CODE128_PATTERNS = [
    '212222','222122','222221','121223','121322','131222','122213','122312','132212','221213',
    '221312','231212','112232','122132','122231','113222','123122','123221','223211','221132',
    '221231','213212','223112','312131','311222','321122','321221','312212','322112','322211',
    '212123','212321','232121','111323','131123','131321','112313','132113','132311','211313',
    '231113','231311','112133','112331','132131','113123','113321','133121','313121','211331',
    '231131','213113','213311','213131','311123','311321','331121','312113','312311','332111',
    '314111','221411','431111','111224','111422','121124','121421','141122','141221','112214',
    '112412','122114','122411','142112','142211','241211','221114','413111','241112','134111',
    '111242','121142','121241','114212','124112','124211','411212','421112','421211','212141',
    '214121','412121','111143','111341','131141','114113','114311','411113','411311','113141',
    '114131','311141','411131','211412','211214','211232','2331112'
  ];

  /**
   * Short, scanner-friendly value. Long invoice strings (POS-L-<timestamp>) used to
   * scale bars so thin phones/websites could not read them — keep ≤12 chars and
   * prefer digits-only so Code128C encodes denser + clearer.
   * Return lookup MUST use saleMatchesReceiptScan() — do not expect exact invoice match.
   */
  function receiptBarcodeValue(sale) {
    var raw =
      (sale && (
        sale.invoiceNumber ||
        sale.orderNumber ||
        sale.orderNo ||
        sale.saleNumber ||
        sale.receiptNo ||
        sale.id ||
        sale._id
      )) || '';
    var s = String(raw).replace(/^local-sale-/i, '').replace(/\s+/g, '');
    var digits = s.replace(/\D/g, '');
    // Pure numeric payload scans most reliably (Code128C)
    if (digits.length >= 8) return digits.slice(-12);
    var cleaned = s.replace(/[^A-Za-z0-9]/g, '').toUpperCase();
    if (cleaned.length > 12) cleaned = cleaned.slice(-12);
    return cleaned || 'RECEIPT';
  }

  /** Digits only, strip leading zeros (Code128C may pad a leading 0). */
  function receiptScanDigits(v) {
    var d = String(v || '').replace(/\D/g, '');
    d = d.replace(/^0+/, '');
    return d;
  }

  /**
   * True when a scanned receipt barcode / typed invoice matches this sale.
   * Handles full invoice (POS-L-…), id, and the short numeric Code128 on the receipt.
   */
  function saleMatchesReceiptScan(sale, scanned) {
    var raw = String(scanned || '').trim();
    if (!raw || !sale) return false;
    var n = function (v) { return String(v || '').trim().toLowerCase(); };
    var fields = [
      sale.invoiceNumber,
      sale.orderNumber,
      sale.orderNo,
      sale.saleNumber,
      sale.receiptNo,
      sale.id,
      sale._id,
      receiptBarcodeValue(sale),
    ];
    for (var i = 0; i < fields.length; i++) {
      if (fields[i] && n(fields[i]) === n(raw)) return true;
    }
    var scanDig = receiptScanDigits(raw);
    if (scanDig.length < 6) return false;
    for (var j = 0; j < fields.length; j++) {
      var fd = receiptScanDigits(fields[j]);
      if (!fd) continue;
      if (fd === scanDig || fd.endsWith(scanDig) || scanDig.endsWith(fd)) return true;
    }
    return false;
  }

  function code128ModuleWidth(codes) {
    var n = 0;
    for (var i = 0; i < codes.length; i++) {
      var pat = CODE128_PATTERNS[codes[i]];
      if (!pat) return 0;
      for (var d = 0; d < pat.length; d++) n += Number(pat[d]);
    }
    return n;
  }

  /** Encode as Code128C (pairs of digits) when possible, else Code128B. */
  function encodeCode128(text) {
    var t = String(text || '');
    var useC = /^\d+$/.test(t) && t.length >= 2;
    if (useC && t.length % 2 === 1) t = '0' + t; // Code128C needs even length

    var codes = [];
    var sum = 0;
    if (useC) {
      codes.push(105); // Start C
      sum = 105;
      var pos = 1;
      for (var i = 0; i < t.length; i += 2) {
        var pair = Number(t.slice(i, i + 2));
        codes.push(pair);
        sum += pair * pos;
        pos += 1;
      }
    } else {
      codes.push(104); // Start B
      sum = 104;
      for (var j = 0; j < t.length; j++) {
        var v = t.charCodeAt(j) - 32;
        if (v < 0 || v > 94) v = 0; // fallback to space
        codes.push(v);
        sum += v * (j + 1);
      }
    }
    codes.push(sum % 103);
    codes.push(106); // Stop
    return { codes: codes, text: t, set: useC ? 'C' : 'B' };
  }

  /** Code128 → standalone inline <svg> (thick bars + quiet zone so phones can scan). */
  function code128BarcodeSvg(value, paperWidth) {
    try {
      var text = String(value || 'RECEIPT').replace(/[^A-Za-z0-9]/g, '').toUpperCase();
      if (!text) text = 'RECEIPT';

      var maxInner = Math.max(200, (Number(paperWidth) || 320) - 16);
      var module = 3;          // px per narrow bar — keep thick for phone cameras
      var quietMods = 10;      // quiet zone ≥ 10 modules (Code128 spec)
      var height = 70;
      var encoded = encodeCode128(text);
      var modulesWide = code128ModuleWidth(encoded.codes) + quietMods * 2;

      // Prefer shortening the payload over shrinking bar width (thin bars won't scan)
      while (modulesWide * module > maxInner && text.length > 8) {
        text = text.slice(-Math.max(8, text.length - 2));
        encoded = encodeCode128(text);
        modulesWide = code128ModuleWidth(encoded.codes) + quietMods * 2;
      }
      if (modulesWide * module > maxInner) module = 2;

      var quiet = quietMods * module;
      var x = quiet;
      var bars = '';
      for (var c = 0; c < encoded.codes.length; c++) {
        var pat = CODE128_PATTERNS[encoded.codes[c]];
        if (!pat) return '';
        for (var d = 0; d < pat.length; d++) {
          var w = Number(pat[d]) * module;
          if (d % 2 === 0) {
            bars += '<rect x="' + x + '" y="0" width="' + w + '" height="' + height + '" fill="#000"/>';
          }
          x += w;
        }
      }
      var totalW = x + quiet;
      var totalH = height + 4;

      // Do NOT CSS-shrink the SVG (max-width:100%) — that recreates unreadable thin bars.
      return (
        '<svg xmlns="http://www.w3.org/2000/svg" width="' + totalW + '" height="' + totalH + '"' +
        ' viewBox="0 0 ' + totalW + ' ' + totalH + '"' +
        ' shape-rendering="crispEdges"' +
        ' style="display:block;margin:0 auto;background:#fff;">' +
        '<rect width="100%" height="100%" fill="#ffffff"/>' +
        bars +
        '</svg>' +
        '<div style="text-align:center;font-size:11px;font-weight:400;letter-spacing:1.5px;margin-top:4px;font-family:monospace;">' +
        esc(encoded.text) +
        '</div>'
      );
    } catch (err) {
      return '';
    }
  }


  function sampleReceiptSale() {
    var now = Date.now();
    return {
      invoiceNumber: 'INV-100248',
      createdAt: new Date(now).toISOString(),
      customerName: 'Ahmed Raza',
      customerPhone: '+92 300 1234567',
      cashierName: 'Bilal Khan',
      terminalName: 'Terminal 01',
      locationName: 'Gulberg Store',
      items: [
        { productName: 'Basmati Rice', sku: 'RICE-001', quantity: 1.5, unitName: 'KG', unitPrice: 280, lineTotal: 420, taxRate: 0 },
        { productName: 'Pepsi Black 500ml', sku: 'KASHIF-0003', quantity: 1, unitName: 'Pcs', unitPrice: 90, lineTotal: 90, taxRate: 0 },
        { productName: 'Cooking Oil', sku: 'OIL-001', quantity: 0.75, unitName: 'LTR', unitPrice: 520, lineTotal: 390, taxRate: 0 },
      ],
      payments: [{ paymentMethod: 'Cash', amount: 950, reference: '' }],
      subTotal: 900,
      subtotal: 900,
      discountTotal: 10,
      discountAmount: 10,
      taxAmount: 0,
      grandTotal: 890,
      paidAmount: 950,
      changeAmount: 60,
      loyaltyPoints: 485,
      notes: '',
    };
  }

  // ─── Advanced thermal print (mirrors web app printReceiptNode) ─────────────
  var printInProgress = false;
  var printQueue = [];

  function prepareReceiptClone(node) {
    var receiptPaper = node.querySelector && node.querySelector('.pos-receipt-paper')
      ? node.querySelector('.pos-receipt-paper')
      : node;
    var clone = receiptPaper.cloneNode(true);

    var cloneImages = clone.querySelectorAll('img');
    for (var i = 0; i < cloneImages.length; i++) {
      var img = cloneImages[i];
      var src = img.getAttribute('src') || '';
      if (src.startsWith('/')) {
        img.setAttribute('src', window.location.origin + src);
      }
    }

    var sourceCanvases = Array.from(receiptPaper.querySelectorAll('canvas'));
    var cloneCanvases = clone.querySelectorAll('canvas');
    for (var j = 0; j < cloneCanvases.length; j++) {
      var canvasEl = cloneCanvases[j];
      var source = sourceCanvases[j];
      if (!source) continue;
      try {
        var newImg = document.createElement('img');
        newImg.src = source.toDataURL('image/png');
        newImg.className = 'receipt-qr';
        canvasEl.parentNode.replaceChild(newImg, canvasEl);
      } catch (e) {
        /* ignore */
      }
    }
    return clone;
  }

  function finishPrintJob() {
    printInProgress = false;
    processPrintQueue();
  }

  /** Preferred path: mono bitmap via Electron (matches Black Copper self-test solidity). */
  function printReceiptMonoBitmap(clone, widthMm) {
    var api = global.bisonDesktop && global.bisonDesktop.print && global.bisonDesktop.print.thermalReceipt;
    if (typeof api !== 'function') return Promise.reject(new Error('no-thermal-api'));
    return api(clone.outerHTML, Number(widthMm) === 58 ? 58 : 80).then(function (res) {
      if (res && res.ok) return res;
      throw new Error((res && res.error) || 'thermal-print-failed');
    });
  }

  /** Fallback: browser iframe print (can look light on thermal). */
  function printReceiptBrowserIframe(clone, widthMm) {
    var paperWidth = Number(widthMm) === 58 ? 58 : 80;

    var existingIframes = document.querySelectorAll('iframe[title="POS thermal print"]');
    for (var i = 0; i < existingIframes.length; i++) {
      try {
        existingIframes[i].style.display = 'none';
        (function (el) {
          setTimeout(function () {
            try { document.body.removeChild(el); } catch (e) { /* ignore */ }
          }, 1000);
        })(existingIframes[i]);
      } catch (e) { /* ignore */ }
    }

    var iframe = document.createElement('iframe');
    iframe.setAttribute('title', 'POS thermal print');
    iframe.setAttribute('data-print-id', String(Date.now()));
    iframe.style.cssText = 'position:fixed;right:0;bottom:0;width:0;height:0;border:0;opacity:0;pointer-events:none;z-index:-1;';
    document.body.appendChild(iframe);

    var win = iframe.contentWindow;
    var doc = win && win.document;
    if (!doc) {
      try { document.body.removeChild(iframe); } catch (e) { /* ignore */ }
      window.print();
      return;
    }

    // Thermal heads only burn ~72mm of 80mm paper (48mm of 58mm). Laying out at full
    // paper width pushes right-aligned amounts off the printable area (cut words).
    // Black Copper clips the right edge even on its own test page — keep a safety margin.
    var printableWidth = paperWidth === 58 ? 44 : 66;

    var thermalCss =
      '@page{size:' + paperWidth + 'mm auto;margin:0;}' +
      '@media print{' +
      '@page{size:' + paperWidth + 'mm auto;margin:0;}' +
      'body{width:' + printableWidth + 'mm!important;max-width:' + printableWidth + 'mm!important;}' +
      '*{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important;}' +
      '}' +
      '*{box-sizing:border-box;}' +
      'html,body{margin:0;padding:0;background:#fff;color:#000;}' +
      'body{width:' + printableWidth + 'mm;max-width:' + printableWidth + 'mm;margin:0;}' +
      'html,body,.pos-receipt-paper,.pos-receipt-paper *{color:#000!important;}' +
      // Courier New strokes are ~1 dot wide at 203dpi; Windows anti-aliases them to gray and
      // the driver dithers gray into broken/light glyphs. Bold sans prints solid black.
      'body,.pos-receipt-paper,.pos-receipt-paper *{font-family:Arial,Tahoma,"Segoe UI",sans-serif!important;' +
      'text-rendering:geometricPrecision;-webkit-font-smoothing:none;}' +
      'body{font-size:12px;line-height:1.3;}' +
      // Tiny 10–11px lines (SKU, policy, footer) are the ones that drop out first.
      '.pos-receipt-paper [style*="font-size:10px"],.pos-receipt-paper [style*="font-size:11px"]{font-size:12px!important;}' +
      '.pos-receipt-paper div,.pos-receipt-paper td{overflow-wrap:anywhere;word-break:break-word;}' +
      '.pos-receipt-paper{width:100%!important;max-width:100%!important;margin:0;padding:2px 2px 30px 2px;background:#fff;}' +
      '.pos-receipt-paper [style*="padding:14px 12px"]{padding:4px 2px!important;}' +
      '.no-print{display:none!important;}' +
      'img{max-width:100%;height:auto;display:block;margin:0 auto;}' +
      'table{width:100%;border-collapse:collapse;}' +
      'svg{max-width:100%;height:auto;display:block;margin:2px auto;}' +
      'div,p{margin:0;padding:0;}';

    doc.open();
    doc.write(
      '<!DOCTYPE html><html><head><meta charset="utf-8"/><title>Receipt</title><style>' +
      thermalCss +
      '</style></head><body>' + clone.outerHTML + '</body></html>'
    );
    doc.close();

    var printed = false;
    var printId = iframe.getAttribute('data-print-id');
    var cleanup = function () {
      setTimeout(function () {
        try {
          var currentIframe = document.querySelector('iframe[data-print-id="' + printId + '"]');
          if (currentIframe) document.body.removeChild(currentIframe);
        } catch (e) { /* ignore */ }
        finishPrintJob();
      }, 8000);
    };

    var printWhenReady = function () {
      if (printed) return;
      printed = true;
      try {
        win.focus();
        win.print();
        cleanup();
      } catch (e) {
        console.error('[POS] Print error', e);
        finishPrintJob();
        window.print();
      }
    };

    var images = Array.from(doc.images);
    if (!images.length) {
      setTimeout(printWhenReady, 400);
      return;
    }
    var remaining = images.length;
    var done = function () {
      remaining -= 1;
      if (remaining <= 0) setTimeout(printWhenReady, 250);
    };
    for (var k = 0; k < images.length; k++) {
      if (images[k].complete) done();
      else {
        images[k].onload = done;
        images[k].onerror = done;
      }
    }
    setTimeout(function () { if (!printed) printWhenReady(); }, 5000);
  }

  function printReceiptNode(node, widthMm) {
    if (typeof document === 'undefined') {
      throw new Error('Cannot print - document not available');
    }

    if (printInProgress) {
      printQueue.push({ node: node, widthMm: widthMm });
      console.log('[POS] Print queued - another print in progress');
      return;
    }

    printInProgress = true;
    var clone;
    try {
      clone = prepareReceiptClone(node);
    } catch (e) {
      console.error('[POS] Print failed', e);
      finishPrintJob();
      window.print();
      return;
    }
    // Mono bitmap prints solid black regardless of driver halftoning; the main process
    // sets an exact page height so there is no long blank feed. Iframe print is the fallback.
    printReceiptMonoBitmap(clone, widthMm).then(finishPrintJob, function (err) {
      if (err && /cancel/i.test(String(err.message))) {
        finishPrintJob();
        return;
      }
      console.warn('[POS] Mono print unavailable, using browser print', err);
      try {
        printReceiptBrowserIframe(clone, widthMm);
      } catch (e) {
        console.error('[POS] Print failed', e);
        finishPrintJob();
        window.print();
      }
    });
  }

  function processPrintQueue() {
    if (printQueue.length > 0) {
      var next = printQueue.shift();
      setTimeout(function() {
        printReceiptNode(next.node, next.widthMm);
      }, 500);
    }
  }

  /**
   * Replace receipt scan-code block with company Labels design (barcode format/colors + QR).
   * Encodes the same receipt # value so returns scanning still works.
   */
  async function applyLabelScanCodes(rootEl, sale) {
    if (!rootEl) return;
    var nodes = rootEl.querySelectorAll
      ? rootEl.querySelectorAll('.receipt-scan-codes')
      : [];
    if (!nodes.length) return;

    var value = receiptBarcodeValue(sale || {});
    var api = global.bisonDesktop;
    var bcTpl = null;
    var qrTpl = null;
    try {
      if (api && api.labels) {
        var bRes = await api.labels.getDefault('barcode');
        var qRes = await api.labels.getDefault('qr');
        if (bRes && bRes.success) bcTpl = bRes.data;
        if (qRes && qRes.success) qrTpl = qRes.data;
      }
    } catch (e) {
      console.warn('[receipt] label template load failed', e);
    }

    for (var i = 0; i < nodes.length; i++) {
      var node = nodes[i];
      var code = node.getAttribute('data-receipt-code') || value;
      var paperWidth = Number(node.getAttribute('data-paper-width')) || 320;
      var parts = [];

      // Barcode — use Labels format/colors when safe; receipt ids stay CODE128 if EAN/UPC won't fit
      var bc = (bcTpl && bcTpl.barcode) || {};
      var format = String(bc.format || 'CODE128').toUpperCase();
      var safeFormat = (format === 'CODE39' || format === 'CODE128') ? format : 'CODE128';
      var barColor = bc.barColor || '#000000';
      var drewBc = false;
      try {
        if (api && api.codes && typeof api.codes.barcodeSvg === 'function') {
          var bcRes = await api.codes.barcodeSvg({
            text: code,
            format: safeFormat,
            height: 14,
            scale: 2,
            barColor: barColor,
            bgColor: '#ffffff',
            showText: bc.showText !== false,
            quietZone: bc.quietZone || 8,
          });
          if (bcRes && bcRes.success && bcRes.svg) {
            parts.push('<div style="width:100%;display:flex;justify-content:center;line-height:0;">' + bcRes.svg + '</div>');
            drewBc = true;
          }
        }
      } catch (e) { /* fall through */ }
      if (!drewBc) parts.push(code128BarcodeSvg(code, paperWidth));

      // QR — from Labels QR settings (same receipt code payload)
      var qr = (qrTpl && qrTpl.qr) || {};
      try {
        if (api && api.codes && typeof api.codes.qrSvg === 'function') {
          var size = Math.max(72, Math.min(140, Number(qr.size) || 100));
          var qrRes = await api.codes.qrSvg(code, size, {
            fgColor: qr.fgColor || '#000000',
            bgColor: qr.bgColor || '#ffffff',
            errorCorrection: qr.errorCorrection || 'M',
          });
          if (qrRes && qrRes.success && qrRes.svg) {
            parts.push('<div style="margin-top:8px;display:flex;justify-content:center;line-height:0;">' + qrRes.svg + '</div>');
          }
        }
      } catch (e) { /* ignore */ }

      parts.push('<div style="text-align:center;font-size:10px;font-weight:400;margin-top:6px;">Scan code = receipt #</div>');
      node.innerHTML = parts.join('');
    }
  }

  global.PosReceipt = {
    DEFAULT_RECEIPT_TEMPLATE: DEFAULT_RECEIPT_TEMPLATE,
    loadReceiptTemplate: loadReceiptTemplate,
    saveReceiptTemplate: saveReceiptTemplate,
    resolveReceiptCompany: resolveReceiptCompany,
    buildReceiptHtml: buildReceiptHtml,
    applyLabelScanCodes: applyLabelScanCodes,
    sampleReceiptSale: sampleReceiptSale,
    receiptBarcodeValue: receiptBarcodeValue,
    saleMatchesReceiptScan: saleMatchesReceiptScan,
    code128BarcodeSvg: code128BarcodeSvg,
    money: money,
    printReceiptNode: printReceiptNode,
  };
})(window);